SourceCode.Declaration:
class MwmsLogicBlockStartProductionOrder extends TFMLogicBlock implements TFMLogicBlockDataCollectionInterface
{
    ProdTable           prodTable;

}

Method.Source:
public str blockIcon()
{
    str ret;

    ret = methodStr(MwmsImageHandlerCombinedImages, productionStart);

    return ret;
}

public Name blockName()
{
    return "Start Production Order";
}

public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    TFMReferenceDataConfiguration headerconf = new TFMReferenceDataConfiguration();
    TFMRegistrationCollectorText prodIdCollector = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(ProdId));
    prodIdCollector.parmOptional(false);
    headerconf.addCollector(prodIdCollector);
    return headerconf;
}

/// <summary>
/// This method gives you the registration collectors for this data collection block.
/// </summary>
/// <returns>A collection of registration collectors.</returns>
public TFMRegistrationCollectors registrationCollectors()
{
    TFMRegistrationCollectors cols = TFMRegistrationCollectors::Construct();
    TFMRegistrationCollectorDecimal qtyCollector = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(Qty));

    cols.addCollector(qtyCollector);

    return cols;
}

/// <summary>
/// This method is called before the post method, and gives the option to add extra registration collectors for the user to be prompted for before the post method is executed.
/// </summary>
/// <returns>Returns a TFMRegistrationCollectors object if the user must be further prompted, otherwise it returns null</returns>
public TFMRegistrationCollectors prePostRegistrationCollectors()
{
    return null;
}

/// <summary>
/// The method executed when all data has been collected, and contains the posting logic.
/// </summary>
/// <returns>A TFMPostResponseData object.</returns>
public TFMPostResponseData post()
{

    ProdMultiStartUp    prodMultiStartUp;
    ProdParmStartUp     prodParmStartUpUpd;
    ProdParmStartUp     prodParmStartUp;
    TFMPostResponseData response = TFMPostResponseData::Construct();
    ProdId              prodId = request.getFieldValue(extendedTypeStr(ProdId));
    Qty                 qty = str2Num(request.getFieldValue(extendedTypeStr(Qty)));

    prodTable = ProdTable::find(prodId);

    if (prodTable)
    {
        ttsbegin;            
        prodMultiStartUp = ProdMultiStartUp::construct(new Args());
        RunBaseMultiParm::initParm(prodMultiStartUp);

        prodParmStartUp= prodMultiStartUp.defaultParmBuffer();

        prodMultiStartUp.insert(prodTable, prodParmStartUp);

        // Overwrite parameters using hardcoded settings
        prodParmStartUpUpd = ProdParmStartUp::find(prodParmStartUp.ParmId, prodParmStartUp.ProdId, true);
        prodParmStartUpUpd.StartUpQty       = qty;
        prodParmStartUpUpd.RouteAutoConsump = RouteAutoConsump::Never;
        prodParmStartUpUpd.bomAutoConsump   = BOMAutoConsump::Never;
        prodParmStartUpUpd.update();

        prodMultiStartUp.run();
        ttscommit;

        response.parmResponseText(strFmt("Production order %1 has been started.", prodId));
    }
    else
    {
        throw error(strFmt("Production order %1 not found.", prodId));
    }
    return response;
}
